{"chunk_id":"14d3c1","wall_time_seconds":0.000006819,"exit_code":0,"original_token_count":3281,"output":""""Small syntax validators used by the CLI implementation."""
import configparser
import csv
import io
import json
import plistlib
import re
try:
    import tomllib
except ImportError:  # Python 3.10 target
    tomllib = None
    class _TomlDecodeError(ValueError): pass
    _TOML_ERROR = _TomlDecodeError
else:
    _TOML_ERROR = tomllib.TOMLDecodeError
import xml.etree.ElementTree as ET


def _jsonc(s):
    # Remove comments while preserving quoted strings and line positions.
    out=[]; i=0; quote=False; esc=False
    while i<len(s):
        c=s[i]
        if quote:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c=='"': quote=False
            i+=1; continue
        if c=='"': quote=True; out.append(c); i+=1; continue
        if s.startswith('//',i):
            while i<len(s) and s[i]!='\n': out.append(' '); i+=1
            continue
        if s.startswith('/*',i):
            out.extend('  '); i+=2
            while i<len(s) and not s.startswith('*/',i):
                out.append('\n' if s[i]=='\n' else ' '); i+=1
            if i<len(s): out.extend('  '); i+=2
            continue
        out.append(c); i+=1
    return ''.join(out)


def _yaml(s):
    # Structural checks for common YAML errors; scalar-heavy files are accepted.
    maps = {}
    for n,line in enumerate(s.splitlines(),1):
        if not line.strip() or line.lstrip().startswith('#') or line.strip() in ('---','...'): continue
        indent=len(line)-len(line.lstrip(' '))
        if '\t' in line[:indent]: return f"line {n}: tabs are not allowed for indentation"
        body=line.strip()
        # Reject repeated keys in a mapping, as the reference YAML parser does.
        # Indentation gives a useful approximation of mapping scope without a
        # third-party YAML parser.
        if not body.startswith('- '):
            m = re.match(r'^(.+?):(?:\s|$)', body)
            if m:
                key = m.group(1).strip()
                for level in list(maps):
                    if level > indent: del maps[level]
                scope = maps.setdefault(indent, {})
                if key in scope:
                    return f'yaml: unmarshal errors:\n  line {n}: mapping key "{key}" already defined at line {scope[key]}'
                scope[key] = n
        if body.startswith((':', '- :')): return f"line {n}: could not find expected ':'"
        if body.count('[')!=body.count(']') and not body.startswith('#'): return f"line {n}: flow sequence is not closed"
        if body.count('{')!=body.count('}') and not body.startswith('#'): return f"line {n}: flow mapping is not closed"
        for q in ('"', "'"):
            if body.count(q)%2: return f"line {n}: found unexpected end of stream"
    return None


def _toml_fallback(text):
    """Conservative TOML structural check for Python versions without tomllib."""
    pending = ''
    start = 0
    balance = 0
    quote = None
    escaped = False
    section = ''
    for n, raw in enumerate(text.splitlines(), 1):
        # Remove comments outside strings and track multiline arrays/tables.
        line = []
        q = quote
        esc = escaped
        for c in raw:
            if q:
                line.append(c)
                if q == '"' and esc: esc = False
                elif q == '"' and c == '\\': esc = True
                elif c == q: q = None
            elif c in ('"', "'"):
                q = c; line.append(c)
            elif c == '#':
                break
            else:
                line.append(c)
        clean = ''.join(line).strip()
        if not clean:
            continue
        if not pending and clean.startswith('['):
            if not re.fullmatch(r'\[\[?[A-Za-z0-9_."-]+\]\]?', clean):
                raise ValueError(f'line {n}: invalid table header')
            section = clean
            continue
        if not pending:
            pending = clean
            start = n
        else:
            pending += ' ' + clean
        # Accumulate until brackets/braces and quoted strings are complete.
        q = None; esc = False; balance = 0
        for c in pending:
            if q:
                if q == '"' and esc: esc = False
                elif q == '"' and c == '\\': esc = True
                elif c == q: q = None
            elif c in ('"', "'"): q = c
            elif c in '[{': balance += 1
            elif c in ']}': balance -= 1
        quote = q
        escaped = esc
        if balance > 0 or quote:
            continue
        if balance < 0: raise ValueError(f'line {start}: unexpected closing bracket')
        x = pending
        pending = ''
        if '=' not in x: raise ValueError(f'line {start}: expected key = value')
        key, val = x.split('=', 1)
        if not key.strip(): raise ValueError(f'line {start}: empty key')
        val = val.strip()
        if val in ('true', 'false') or re.fullmatch(r'[+-]?(?:\d+(?:_\d+)*(?:\.[0-9_]+)?|inf|nan)', val, re.I): continue
        if val.startswith(('"', "'")):
            if len(val) < 2 or val[0] != val[-1]: raise ValueError(f'line {start}: unterminated string')
            continue
        if val.startswith(('[', '{')):
            if val[-1:] not in (']', '}'): raise ValueError(f'line {start}: unclosed array or inline table')
            continue
        if re.fullmatch(r'\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d(?::\d\d(?:\.\d+)?)?(?:Z|[+-]\d\d:\d\d)?)?', val): continue
