    if pending: raise ValueError(f'line {start}: unclosed array, table, or string')


def validate_content(filetype, text, options=None):
    """Return None for valid syntax, otherwise a concise syntax error string."""
    options = options or {}
    t=filetype.lower().replace('-', '').replace('_','')
