def repository_root(path):
    cur = os.path.abspath(path)
    if not os.path.isdir(cur):
        cur = os.path.dirname(cur)
    while True:
        if os.path.exists(os.path.join(cur, ".git")):
            return cur
        parent = os.path.dirname(cur)
        if parent == cur:
            return None
        cur = parent


def _glob_regex(pattern):
    out = ["^"]
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                i += 1
                if i + 1 < len(pattern) and pattern[i + 1] == "/":
                    i += 1
                    out.append("(?:.*/)?")
                else:
                    out.append(".*")
            else:
                out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        elif c == "[":
            end = pattern.find("]", i + 1)
            if end < 0:
                out.append(r"\[")
            else:
                body = pattern[i + 1:end]
                if body.startswith("!"):
                    body = "^" + body[1:]
                out.append("[" + body + "]")
                i = end
        else:
            out.append(re.escape(c))
        i += 1
    out.append("$")
    try:
        return re.compile("".join(out))
    except re.error:
        return re.compile(r"(?!)")


def _read_rules(directory):
    path = os.path.join(directory, ".gitignore")
    try:
        lines = open(path, encoding="utf-8").read().splitlines()
    except (OSError, UnicodeError):
        return []
    rules = []
    for raw in lines:
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        negate = s.startswith("!")
        if negate:
            s = s[1:]
        if s.startswith(r"\#") or s.startswith(r"\!"):
            s = s[1:]
        directory_only = s.endswith("/")
        s = s.rstrip("/")
        anchored = s.startswith("/")
        s = s.lstrip("/")
        if s:
            rules.append((negate, directory_only, "/" in s or anchored,
                          _glob_regex(s), s))
    return rules


def ignored(path, root):
    """Return whether path is ignored by applicable repository .gitignore files."""
    root = os.path.abspath(root)
    path = os.path.abspath(path)
    try:
        rel = os.path.relpath(path, root)
    except ValueError:
        return False
    if rel == ".." or rel.startswith(".." + os.sep):
        return False
    parts = rel.split(os.sep)
    dirs = [root]
    for component in parts[:-1]:
        dirs.append(os.path.join(dirs[-1], component))
    is_dir = os.path.isdir(path)
    ignored_now = False
    for base in dirs:
        try:
            base_rel = os.path.relpath(base, root)
            if base_rel == ".":
                base_rel = ""
            suffix_parts = parts[len(base_rel.split(os.sep)):] if base_rel else parts
        except Exception:
            continue
        suffix = "/".join(suffix_parts)
        if not suffix:
            continue
        for negate, directory_only, has_slash, rx, original in _read_rules(base):
            candidates = ["/".join(suffix_parts[:i]) for i in range(1, len(suffix_parts) + 1)]
            matched = False
            for idx, candidate in enumerate(candidates):
                prefix_is_dir = idx < len(candidates) - 1 or is_dir
                if directory_only and not prefix_is_dir:
                    continue
                if has_slash:
                    if rx.match(candidate):
                        matched = True
                elif fnmatch.fnmatchcase(candidate.split("/")[-1], original):
                    matched = True
                if matched:
                    break
            if matched:
                ignored_now = not negate
    # Git cannot re-include a file while one of its parent directories remains
    # excluded; the ignored directory must first be re-included.
    parent = os.path.dirname(path)
    while parent and parent != root and os.path.commonpath([parent, root]) == root:
        if ignored(parent, root):
            return True
        next_parent = os.path.dirname(parent)
        if next_parent == parent:
            break
        parent = next_parent
